def _get_check_for_user(
    request: HttpRequest, code: UUID, preload_owner_profile: bool = False
) -> tuple[Check, bool]:
    """Return specified check if current user has access to it.

    Returns a (check, rw) tuple. Superusers and project owners get rw=True,
    team members get rw according to their role. Anyone else gets a 404.
    """

    assert request.user.is_authenticated

    fields = ["project"]
    if preload_owner_profile:
        fields.append("project__owner__profile")

    check = get_object_or_404(Check.objects.select_related(*fields), code=code)
    if request.user.is_superuser:
        return check, True

    if request.user.id == check.project.owner_id:
        return check, True

    membership = get_object_or_404(Member, project=check.project, user=request.user)
    return check, membership.is_rw


def _get_rw_check_for_user(request: HttpRequest, code: UUID) -> Check:
    """Like _get_check_for_user, but raise PermissionDenied for read-only members."""

    check, rw = _get_check_for_user(request, code)
    if not rw:
        raise PermissionDenied

    return check


